{
  "id": "T-256",
  "title": "New task specs stay out of version control through .gitignore, specs already tracked stay tracked, and every reader takes the spec from the approved pin or the local file",
  "public_title": null,
  "milestone": "M2",
  "depends_on": [
    "T-251"
  ],
  "scope": [
    ".gitignore",
    "bin/lib/fm_spec_pins.py",
    "bin/lib/fm_binding.py",
    "bin/lib/fm_autopilot.py",
    "bin/fm-worker.sh",
    "bin/fm-review.sh",
    "bin/fm-config.sh",
    "bin/fm-canary.sh",
    "bin/fm.sh",
    "bin/fm-ready.sh",
    "bin/fm-emit.sh",
    "board/server.ts",
