    ".github/ISSUE_TEMPLATE/task-proposal.yml",
    "skills/firstmate/SKILL.md",
    "skills/firstmate/rule-inventory.json",
    "skills/worker/SKILL.md",
    "design/design.md",
    "README.md",
    "bin/fm-decide.sh",
